/* Embedded pictures are recovered only from the selected local workbook; none are bundled. */
(function(root){'use strict';
 const MAX=12*1024*1024;
 function workbookPictures(file,specs){return new Promise((ok,no)=>{let w,url,timer,done=false;const finish=(e,v)=>{if(done)return;done=true;clearTimeout(timer);w?.terminate();if(url)URL.revokeObjectURL(url);e?no(e):ok(v);};try{const code=root.WorkpaperXlsxSource+`;onmessage=e=>{try{const c=XLSX.CFB.read(new Uint8Array(e.data.buffer),{type:'array'}),out=e.data.specs.map(s=>{if(s.stream!=='Workbook'&&s.stream!=='Book')throw Error('stream');const entry=XLSX.CFB.find(c,s.stream);if(!entry?.content)throw Error('missing stream');const raw=entry.content;let length=0;for(const p of s.segments){if(!Number.isInteger(p.offset)||!Number.isInteger(p.length)||p.offset<0||p.length<1||p.offset+p.length>raw.length)throw Error('range');length+=p.length;}if(length>12582912)throw Error('size');const b=new Uint8Array(length);let at=0;for(const p of s.segments){b.set(raw.slice(p.offset,p.offset+p.length),at);at+=p.length;}return b;});postMessage({out},out.map(b=>b.buffer));}catch(e){postMessage({error:true});}};`;url=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));w=new Worker(url);w.onmessage=e=>e.data.error?finish(Error('原工作簿图片无法安全读取；原件未改变')):finish(null,e.data.out);w.onerror=()=>finish(Error('图片隔离读取失败'));timer=setTimeout(()=>finish(Error('图片读取超时')),15000);file.arrayBuffer().then(buffer=>{if(!done)w.postMessage({buffer,specs},[buffer]);},e=>finish(e));}catch(e){finish(e);}});}
 async function load(file,images){if(!Array.isArray(images)||images.length>100)throw Error('原图数量超过本版限制');const out=[],streams=images.filter(s=>s.stream&&Array.isArray(s.segments)),local=images.filter(s=>s.part);let total=0,streamData=streams.length?await workbookPictures(file,streams):[];
  let parts;if(local.length){const a=await root.BidderArchive.open(file,{entryLimit:2048});try{parts=await a.read([...new Set(local.map(s=>s.part))]);}finally{a.close();}}
  for(const spec of images){try{const bytes=spec.stream?streamData[streams.indexOf(spec)]:parts?.get(spec.part);if(!bytes)throw Error('原图暂缺本地读取引用');total+=bytes.length;if(bytes.length>MAX||total>MAX)throw Error('图片体积超出本版限制');if(spec.bytes&&bytes.length!==spec.bytes)throw Error('原图片大小不一致');if(spec.sha256&&await root.ProjectWorkspaceStore.hash(new Blob([bytes]))!==spec.sha256)throw Error('原图片哈希不一致');
   if(['image/png','image/jpeg','image/gif'].includes(spec.mime)){const png=bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71,jpeg=bytes[0]===255&&bytes[1]===216,gif=bytes[0]===71&&bytes[1]===73&&bytes[2]===70;if(!(spec.mime==='image/png'?png:spec.mime==='image/jpeg'?jpeg:gif))throw Error('原图片签名不一致');out.push({spec,bytes});}
   else if(['image/wmf','image/emf','image/dib','image/bmp'].includes(spec.mime)&&root.WorkpaperVectorImages){const blob=await root.WorkpaperVectorImages.toBlob(bytes,spec,{width:Math.abs(spec.bounds?.width)||640,height:Math.abs(spec.bounds?.height)||400});out.push({spec,bytes,blob});}
   else throw Error('原图片格式暂未兼容');
  }catch(e){out.push({spec,error:e.message});}}
  return out;
 }
 async function decorate({container,layout,file,assets}){const canvas=container.querySelector('.pw-original-canvas'),table=canvas?.querySelector('table');if(!canvas||!assets?.length)return;const hiddenCols=new Set(layout.hiddenCols||[]),hiddenRows=new Set(layout.hiddenRows||[]),s=layout.range.s;
  function point(p){let x=0,y=0;for(let c=s.c;c<p.c;c++)if(!hiddenCols.has(c))x+=layout.cols[c]||72;for(let r=s.r;r<p.r;r++)if(!hiddenRows.has(r))y+=layout.rows[r]||17;const row=table.querySelector('[data-original-row="'+p.r+'"]');if(row)y=row.offsetTop;return {x:x+(Number(p.x)||0),y:y+(Number(p.y)||0)};}
  const failed=assets.filter(a=>a.error);if(failed.length){const note=container.ownerDocument.createElement('p');note.className='error';note.textContent=failed.length+'幅原图未能完整显示：'+[...new Set(failed.map(a=>a.error))].join('；')+'。请下载原件核对；未以空白冒充原图。';container.append(note);}const omitted=assets.filter(a=>a.spec.degenerate);if(omitted.length){const note=container.ownerDocument.createElement('p');note.className='pw-original-help';note.textContent=omitted.length+'个原历史图片对象的定位无有效宽高，未人为拉伸；原图片仍保留在本份原件。';container.append(note);}for(const a of assets){if(a.spec.degenerate||a.error)continue;const from=point(a.spec.from),to=point(a.spec.to),img=container.ownerDocument.createElement('img');img.alt='原工作底稿内嵌图片（只读）';img.dataset.workpaperImage=a.spec.sha256||a.spec.part||'original';const url=URL.createObjectURL(a.blob||new Blob([a.bytes],{type:a.spec.mime}));img.src=url;Object.assign(img.style,{position:'absolute',left:from.x+'px',top:from.y+'px',width:Math.max(.1,to.x-from.x)+'px',height:Math.max(.1,to.y-from.y)+'px',objectFit:'fill',pointerEvents:'none',maxWidth:'none'});img.onload=img.onerror=()=>URL.revokeObjectURL(url);canvas.append(img);}
 }
 root.WorkpaperSheetImages=Object.freeze({load,decorate});
})(globalThis);
